public record SaveDashboardRecipePayload(BlockPos position,long desired,String stockMode,long proposalNonce,long recipeEpoch,boolean blockingMode)implements CustomPacketPayload{public static final Type<SaveDashboardRecipePayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(BeyondCraftlines.MOD_ID,"save_dashboard_recipe"));public static final StreamCodec<ByteBuf,SaveDashboardRecipePayload> STREAM_CODEC=StreamCodec.composite(BlockPos.STREAM_CODEC,SaveDashboardRecipePayload::position,ByteBufCodecs.VAR_LONG,SaveDashboardRecipePayload::desired,ByteBufCodecs.stringUtf8(16),SaveDashboardRecipePayload::stockMode,ByteBufCodecs.VAR_LONG,SaveDashboardRecipePayload::proposalNonce,ByteBufCodecs.VAR_LONG,SaveDashboardRecipePayload::recipeEpoch,ByteBufCodecs.BOOL,SaveDashboardRecipePayload::blockingMode,SaveDashboardRecipePayload::new);public static void handle(SaveDashboardRecipePayload p,IPayloadContext c){c.enqueueWork(()->{if(!(c.player() instanceof ServerPlayer player)||!(player.containerMenu instanceof CraftlineOrderMenu menu)||!menu.dashboardConfiguration()||!p.position().equals(menu.dashboardPosition())||!menu.canAccessNetwork(player)||!(player.level().getBlockEntity(p.position()) instanceof CraftlineDashboardBlockEntity d)||!d.mayConfigure(player))return;long now=player.level().getGameTime();var validated=ValidatedClientPlanCache.consume(player.getUUID(),p.proposalNonce(),now);if(p.desired()<1||validated==null||validated.networkId()!=menu.networkId()||validated.count()!=p.desired()||validated.recipeEpoch()!=p.recipeEpoch()||!validated.target().isSame(d.target()))return;long epoch=PlanningSnapshotService.recipeEpoch(player.level(),menu.availableFamilies());if(PlanningFreshness.recipesChanged(validated.recipeEpoch(),epoch))return;var plan=RecipePlanningService.validateFixed(player.level(),d.target(),p.desired(),PlanningSnapshotService.capture(menu.networkId()),menu.availableFamilies(),validated.overrides());if(!validated.overrides().completelyResolves(plan))return;if(!d.configure(player,d.target(),p.desired(),DashboardStockMode.byId(p.stockMode()),d.redstoneMode()))return;d.saveRecipe(player,new DashboardRecipeConfig(validated.overrides(),p.blockingMode()));});}@Override public @NotNull Type<? extends CustomPacketPayload> type(){return TYPE;}}
